<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useI18n } from 'vue-i18n';
import HeroCarousel from '../components/HeroCarousel.vue';
import { listProducts, materialPhoto, type ApiProduct } from '../api';
const {locale}=useI18n();
const tx=(z:string,e:string)=>locale.value==='zh'?z:e;
const products=ref<ApiProduct[]>([]),error=ref('');
const lang=computed(()=>locale.value==='en'?'en':'zh');
const name=(p:ApiProduct)=>(lang.value==='en'?p.name_en:p.name_zh).replace(/\s*[（(](示例|Sample)[）)]/g,'');
const descriptions:Record<string,[string,string]>={aluminium:['简洁线条，轻盈质感。','Clean lines. A lighter touch.'],timber:['自然纹理，温暖层次。','Natural grain. A warmer perspective.'],composite:['柔和表面，平衡光与私密。','Soft surfaces. Balanced light and privacy.']};
onMounted(async()=>{try{products.value=await listProducts()}catch{error.value=tx('暂时无法加载产品，请稍后重试。','Products could not be loaded. Please try again later.')}});
</script>
