  <section class="project-cta"><span class="section-label">{{tx('从一个好问题开始','START WITH A CONVERSATION')}}</span><h2>{{tx('你的下一份项目，\n从这里开始。','Your next project\nstarts here.')}}</h2><router-link to="/portal" class="button">{{tx('进入客户门户','Open the customer portal')}} ↗</router-link><router-link to="/about" class="cta-about">{{tx('了解 VERA','About VERA')}} →</router-link></section>
